120	func gemvActivation(dev *vk.Device, N int) (*vk.Buffer, []float32, error) {
121		x, err := dev.NewBuffer(N * 4)
122		if err != nil {
123			return nil, nil, err
124		}
125		xData := randomFloats(N)
126		x.WriteFloat32(xData)
127		return x, xData, nil
128	}
129	
130	func cpuGEMV(w, x []float32, M, N int) []float32 {
131		y := make([]float32, M)
132		for m := 0; m < M; m++ {
133			var acc float32
134			base := m * N
135			for n := 0; n < N; n++ {
136				acc += w[base+n] * x[n]
137			}
138			y[m] = acc
139		}
140		return y
141	}
142	
143	func compareVec(got, want []float32, relTol float32) error {
144		for i := range want {
145			if !approxEqual(got[i], want[i], relTol) {
146				return fmt.Errorf("mismatch at %d: got %v want %v", i, got[i], want[i])
147			}
148		}
149		return nil
150	}
