152	func runGEMVFloat(dev *vk.Device, mod *vk.ShaderModule, variant, weightFormat string, groupsX uint32, M, N int, warmup, iters uint32, isF16 bool) (Result, error) {
153		wData := randomFloats(M * N)
154	
155		elemSize := 4
156		if isF16 {
