166		} else {
167			wBuf.WriteFloat32(wData)
168		}
169	
170		scalesBuf, err := dev.NewBuffer(4) // dummy, unused by the f32/f16 shader path
171		if err != nil {
172			return Result{}, err
173		}
174		defer scalesBuf.Destroy()
