182		if err != nil {
183			return Result{}, err
184		}
185		defer y.Destroy()
186	
187		pipe, err := dev.NewPipeline(mod, vk.PipelineSpec{
188			Buffers:          []*vk.Buffer{wBuf, scalesBuf, x, y},
189			PushConstantSize: 12,
190		})
191		if err != nil {
192			return Result{}, err
193		}
194		defer pipe.Destroy()
195	
196		pc := newPC().U32(uint32(M)).U32(uint32(N)).U32(0).Bytes()
197	
198		if _, err := pipe.DispatchTimed(groupsX, 1, 1, 1, pc); err != nil {
199			return Result{}, err
200		}
201		got := y.ReadFloat32(M)
