207			tol = 5e-3
208		}
209		want := cpuGEMV(refW, xData, M, N)
210		if err := compareVec(got, want, tol); err != nil {
211			return Result{}, fmt.Errorf("correctness check failed: %w", err)
212		}
213	
214		ns, clocks, err := TimeDispatch(pipe, groupsX, 1, 1, warmup, iters, pc)
215		if err != nil {
