// bytesToInt8 reinterprets raw bytes as the signed int8 lanes a shader
// reading them as packed int8 will see.
func bytesToInt8(b []byte) []int8 {
	out := make([]int8, len(b))
	for i, v := range b {
		out[i] = int8(v)
	}
	return out
}
